        {"coordinate": "clientconn.go:1234", "text": "acCtx := ac.ctx; if acCtx.Err() != nil { ac.mu.Unlock(); return }"},
        {"coordinate": "clientconn.go:1254", "text": "ac.updateConnectivityState(connectivity.Connecting, nil)\n\tac.mu.Unlock()"}
      ]
    }
  ]
